// lib/engine/packs/scuola_guida.js
//
// Sector Pack "scuola_guida" v1 — conoscenza di SETTORE (autoscuola in Italia,
// non di una singola scuola). In lib/settori.js il "cliente" è l'Allievo e
// l'"evento" è la Lezione. Prezzi, quote, orari, sedi, istruttori, mezzi,
// convenzioni, date d'esame e tempi effettivi NON stanno qui: arrivano solo dai
// dati del tenant (o dalla segreteria della scuola).
//
// Note di progetto (specifiche del settore):
//  - L'urgenza è RARA: di norma un'autoscuola riceve iscrizioni, prenotazioni di
//    guide, domande su patenti/esami/documenti. Le uniche urgenze vere sono gli
//    incidenti o i malori durante una guida/lezione: ferito o pericolo -> 112 e
//    avviso a una persona della scuola (CRITICAL); danni senza feriti, incidente
//    "generico" -> HIGH (priorità alla scuola, nessun consiglio).
//  - Date e ESITI d'esame non sono garantiti: il bot non promette promozioni,
//    tempi ("patente in X settimane"), numero di guide sufficienti, né dice
//    quando "sarà" l'esame di un singolo allievo (lo sa la segreteria -> persona).
//  - Il bot NON dà certezze normative: idoneità medica, validità di foglio rosa o
//    patente, sanzioni/punti/sospensioni, alcol, limiti dei neopatentati, ricorsi.
//    Dà solo informazioni generali (documenti, visita medica, età per categoria,
//    fasi del percorso) e rimanda alla scuola per i requisiti del caso concreto.
//  - Allievo minorenne: per gli aspetti contrattuali serve un genitore (o chi
//    esercita la responsabilità): l'iscrizione di un minore passa a una persona.
//  - Attenzione ai limiti del motore: "guida" da sola NON è nel lessico (compare in
//    "scuola guida"); "patente a" da sola neppure ("patente a punti"); il fuzzy
//    (1 refuso su parole >= 6 lettere) impone di non usare parole a distanza 1
//    da termini critici.

export const SETTORE = 'scuola_guida';
export const VERSIONE = 1;
export const CHANGELOG = 'v1: primo Sector Pack scuola guida — lessico patenti (AM, A1, A2, A, B, BE, C, D, CQC), lezioni di guida e teoria, esami, pratiche (rinnovo, recupero punti, duplicato, conversione), minorenni, 28 intent, 12 entità, urgenze (incidente/malore in guida CRITICAL con 112, danni HIGH), sicurezza su idoneità medica/normativa/promesse d\'esame, FAQ di settore generali senza importi né orari.';

// ---- helper ----
const prodotto = (...liste) => liste.reduce((acc, l) => acc.flatMap((a) => l.map((b) => (a ? (b ? `${a} ${b}` : a) : b))), ['']);
const unici = (arr) => [...new Set(arr)];

// Incidente/caduta in guida (CRITICAL): (evento) x (contesto di guida o lezione).
const EVENTI_INCIDENTE = ['incidente', 'tamponamento', 'scontro', 'schianto', 'caduta', 'sinistro', 'fuori strada', 'malore', 'svenimento', 'svenuto', 'svenuta', 'sono caduto', 'sono caduta', 'siamo caduti', 'sono scivolato', 'sono scivolata', 'ho tamponato', 'abbiamo tamponato'];
const CONTESTI_GUIDA = [
  'durante la guida', 'durante una guida', 'durante la lezione', 'durante la lezione di guida', 'durante l esame', 'durante la prova', 'durante la prova pratica',
  'in guida', 'alla guida', 'con l istruttore', 'con l istruttrice', 'con la macchina della scuola', 'con l auto della scuola', 'con la moto della scuola',
  'con lo scooter della scuola', 'con il motorino della scuola', 'con la macchina dell autoscuola', 'con l auto dell autoscuola', 'con la moto dell autoscuola',
  'mentre guidavo', 'mentre guidava', 'mentre guidiamo', 'mentre guido', 'mentre eravamo in guida', 'mentre eravamo in macchina', 'mentre ero in guida', 'mentre ero alla guida',
];
// "incidente in moto durante la prova": il mezzo si inserisce tra evento e contesto (il motore non ha prossimità).
const MEZZI_IN_MEZZO = ['in moto', 'in auto', 'in macchina', 'in scooter', 'con la moto', 'con la macchina', 'con l auto', 'con lo scooter'];
const CONTESTI_CORE = ['durante la guida', 'durante una guida', 'durante la lezione', 'durante l esame', 'durante la prova', 'durante la prova pratica', 'con l istruttore', 'mentre guidavo'];
const CRITICAL_INCIDENTE = unici([...prodotto(EVENTI_INCIDENTE, CONTESTI_GUIDA), ...prodotto(['incidente', 'tamponamento', 'scontro', 'caduta'], MEZZI_IN_MEZZO, CONTESTI_CORE)]);

// Minorenni: "ho 16 anni", "ha 15 anni", "di 17 anni", "sedicenne", ...
const ETA_NUM = ['14', '15', '16', '17'];
const ETA_PAROLE = ['quattordici', 'quindici', 'sedici', 'diciassette'];
const ETA_FORME = unici([...ETA_NUM, ...ETA_PAROLE]);
const MINORENNE_ETA = prodotto(['ho', 'ha', 'di', 'compie', 'faccio', 'fa', 'ho appena compiuto', 'ha appena compiuto', 'ho compiuto', 'ha compiuto'], ETA_FORME, ['anni']);

